<?php
namespace App\Http\Controllers; use App\Http\Requests\StudentRequest; use App\Models\{SchoolClass,Student}; use App\Services\StudentBarcodeService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class StudentController extends Controller{public function index(Request $r){$q=Student::with('schoolClass')->when($r->user()->isWali(),fn($q)=>$q->where('class_id',$r->user()->class_id))->when($r->class_id,fn($q,$v)=>$q->where('class_id',$v))->when($r->search,fn($q,$v)=>$q->where(fn($x)=>$x->where('name','like',"%$v%")->orWhere('nis','like',"%$v%")->orWhere('nisn','like',"%$v%")));return view('students.index',['students'=>$q->latest()->paginate(15)->withQueryString(),'classes'=>SchoolClass::orderBy('class_name')->get()]);}public function create(){return view('students.form',['student'=>new Student,'classes'=>SchoolClass::all()]);}public function store(StudentRequest $r,StudentBarcodeService $barcode){$data=$r->validated();$data['barcode_token']=$barcode->generateToken();if($r->hasFile('photo'))$data['photo']=$r->file('photo')->store('students','public');Student::create($data);return redirect()->route('students.index')->with('success','Siswa berhasil ditambahkan.');}public function show(Student $student){$this->guard($student);return view('students.show',compact('student'));}public function edit(Student $student){return view('students.form',['student'=>$student,'classes'=>SchoolClass::all()]);}public function update(StudentRequest $r,Student $student){$data=$r->validated();if($r->hasFile('photo'))$data['photo']=$r->file('photo')->store('students','public');$student->update($data);return redirect()->route('students.index')->with('success','Data siswa diperbarui.');}public function destroy(Student $student){$student->delete();return back()->with('success','Siswa dihapus.');}public function regenerate(Student $student,StudentBarcodeService $s){$this->authorizeAdmin();$s->regenerate($student);return back()->with('success','Barcode baru dibuat; barcode lama tidak berlaku.');}private function guard(Student $s){if(auth()->user()->isWali())abort_unless((int)$s->class_id===(int)auth()->user()->class_id,403);}private function authorizeAdmin(){abort_unless(auth()->user()->isAdmin(),403);}}
